image/effect/particle_arfairy.tjs.source:
[
	// 共通設定
	%[
	version:1, // バージョン
	rows:1,                       // (int)パターン縦枚数（連続切り替え）
	columns:3,                    // (int)パターン横枚数（パターン種類）
	patsp: 0,                     // (range)パターン速度
	//ctx: void,                  // (int:optional)志向性用基点位置
	//cty: void,                  // (int:optional)志向性用基点位置

	angle: "0/360",               // (range)開始角度
//	speed: "30/90",            // (range)開始スピード
	genpos: %[ x:"0/1280", y:"0/720" ], // 生成位置
	vibsp: "0.05/0.2",             // (range)ゆれ速度
//	vibsz: "32/128",                // (range)ゆれ幅
	genratio:0,                    // (int)生成頻度

	life: "2000/4000",              // (range)維持時間, 0で無限（term必須）
	fade: -500,                      // (int)フェード時間
		],

	// -------------------------------------------------------
	// 個別上書き

	%[ storage:"particle_arfairy2", speed:"20/40", vibsz: "10/20", genratio: 4 ], // ptidx = 1
	%[ storage:"particle_arfairy1", speed:"30/60", vibsz: "20/40", genratio: 2 ], // ptidx = 2

	// ED用
	%[ storage:"particle_arfairy3", speed:"20/60", vibsz: "10/40", genratio: 3, columns:6 ], // ptidx = 3
]

