		"helptextman.tjs",			// ヘルプ表示機能処理ベース／★OptionModule／▼FileStoreModule／◆ExGalleryModule
//		"facethumbdraw.tjs",		// 汎用顔窓描画処理ベース（※要backlog.tjs）

		// ■メッセージ表示拡張
