		eye_tiy:	"日野原ちよ子",
		eye_asa:	"鷺澤有里咲",
		];

	var r = "";
	var file = ((string)Storages.extractStorageName(parser.curStorage)).toLowerCase();
	r += (mp.charfile != "") ? (string)textmap[mp.charfile.toLowerCase()] : "";
	r += "PreStory" if (file != "" && file.indexOf("_ex.") > 0);
	r += han2zen("（%d月%d日）".sprintf(+mp.month, +mp.t)) if (mp.month != "" && mp.t != "");
	dm("MakeEyeCatchAutoSaveText", r);
	return r;
}


//★愛乃亜周回処理用
function menoa_branch(tag, recollection) {
	var prefix = "menoa_cnt_"; // 回想記録用プレフィクス
	if (recollection) {
		// 回想中かどうか
		if (tag == "") kag.warning("menoa回想カウントを取得できません（※現在の状態を利用します）");
		else {
			var cnt = sf[prefix+tag];
			if (cnt !== void) {
				dm("menoa_branch(%s,recollection) = %d".sprintf(tag, cnt));
				return +cnt;
			}
			kag.warning("menoa回想カウントが記録されていません（※現在の状態を利用します）:"+tag);
		}
	}
	var menoa = 0;
	var alltags = [], map = %[], flags = SystemConfig.MenoaFlags;
	for (var i = 0, cnt = flags.count; i < cnt; i+=2) {
		var ref = flags[i], name = flags[i+1];
		if (ref != "" && name != "") {
			alltags.add(ref);
			map[ref] = name;
			var on = sf[name];
			if (on || ref == tag) {
				kag.warning("指定のmenoaフラグが立っていないため補正します:%s(sf.%s)".sprintf(tag,name)) if (!on && ref == tag);
				sf[name] = true;
				menoa++;
			}
		}
	}
	if (tag != "" && menoa > 0) {
		if (sf[prefix+tag] === void)
		/**/sf[prefix+tag] = menoa; // 回想用のカウントを記録

		// menoa_cnt_* の変数が正しい状態か同かをチェック
		var used = [], mask = 0, fix = false;
		for (var i = 0; i < alltags.count; i++) {
			var ref= alltags[i], cnt = sf[prefix+ref], opened = sf[map[ref]];
			if (opened) {
				used.add(ref);
				if (cnt < 1 || cnt > menoa) fix = true; // オープン済みなのにcnt情報がない・値が範囲外
				else mask |= (1 << (cnt-1)); // フラグ記録
			} else if (cnt !== void) fix = true; // 未オープンなのにカウント情報がある
		}
		dm("menoa check %d = 0x%x".sprintf(menoa, mask));
		if (mask != ((1<<menoa)-1)) fix = true; // 全種類使用済みかどうか？
		if (fix) {
			// 自動補正
			kag.warning("menoa回想カウント情報が正しい状態になっていません。自動補正を試みます");
			used.remove(tag,true);
			used.add(tag);
			if (used.count != menoa) {
				dm("menoa count mismatched?", menoa, used*);
			}
			var compare = function(a,b) { return sf[prefix +a] < sf[prefix +b]; } incontextof %[ sf:sf, prefix:prefix ];
			used.sort(compare, true); // 小さい順にソート
			for (var i = alltags.count-1; i >= 0; --i) {
				var ref= alltags[i];
				if (ref != "") delete sf[prefix+ref];
			}
			for (var i = 0; i < used.count; i++) {
				var key = prefix+used[i], value = i+1;
				sf[key] = value;
				dm(key, value);
			}
		}
	}

	dm("menoa_branch(%s) = %d".sprintf(tag, menoa));
	return menoa;
}


function GetBGMLabel(label, storage, defval) {
	if (label == "") return 0;
	if (storage == "") storage = defval;
	var file = storage != "" ? getExistVoice(storage) : void;
	var r = 0;
	if (file != "" && Storages.isExistentStorage(file+".sli")) try {
		var wave = new WaveSoundBuffer(null);
		wave.open(file);
		var info = wave.labels[label];
		if (info) r = info.position;
		invalidate wave;
	} catch (e) {}
	return r;
}

