function GetClearFlagState(chrs = SystemConfig.ClearFlagState) {
	var cnt = 0, total = 0, r = %[];
	for (var i = 0; i < chrs.count; i++) {
		var tag = chrs[i];
		if (tag == "") continue;
		total++;
		var clr = r["_"+tag] = (sf["clear_"+tag] || tf.allseen);
		if (clr) cnt++;
	}
	r.count = cnt;
	r.max   = total;
	r.all = (cnt == total);
	r.any = (cnt > 0);
	return r;
}
