// 環境初期化処理
function initialEnvironment(isFirst = false, tag)
{
	var section = function (sec) { return tag == "" || tag == sec; } incontextof %[ tag:tag ];
	// tag == { "1system", "2text", "3sound", "4voice", "5dialog", "7mouse" } ※"6keys"は設定項目なし
	dm("initEnv", tag);

	// util funcs
	var sysarg = isFirst ? setDefaultSystemArgument : setSysArgMenuItem;
	var chvol = kag.setVoiceVolume;
	var scf = kag.scflags;
	var SC = SystemConfig, SA = SystemAction;

	//--------------------------------------------------------------
	if (section("1system")) {
		var isfull = false;					// false=window, true=fullscreen
		SA[isfull?"_fullscreen":"_window"]() if (!isFirst);

		// [TODO] ワイドスクリーン

		// ウィンドウサイズ初期値
		kag.menuItemClickByKey("resetWindowSizeMenuItem") if (!isfull);

		// エフェクト・速度
		kag.noeffect = false;
		kag.drawspeed = 1;

		(SC.showAutoSkipIcon = 
		 SC.showAutoSkipMark = true);		// オートスキップアイコン
		SC.showSystemIndicator = true;		// 情報インジケータ

		SC.forceSkipMovie = false;			// ムービースキップ

		sysarg("curmove", "yes");			// カーソル自動移動 ("yes":on, "no":off)

		scf.hideMouseCursorTime = SC.mscurHideTime; // マウスカーソル自動消去 (OFFの場合は0)
		try { kag.updateHideMouseCursorTimer(); } catch {} // 即反映

		SC.rightClickType = 0;				// 右クリック機能(0:ウインドウ消去, 1:システムメニュー, 2:バックログ)

		sysarg("mousecursor", "design");	// カーソル形状 ("system":アロー, "design":ちぇし)
	}

	//--------------------------------------------------------------
	if (section("2text")) {
		kag.textspeed   = 50;					// テキスト速度(100:瞬間-0:遅い)

		sf.windowOpac   = 192;					// メッセージ窓不透明度(0-255)

		kag.allskip     = false;				// 未読スキップ (true:有効, false:無効)
		kag.afterskip   = true;					// 選択後の skip (true:継続, false:停止)

		kag.autospeed   = 50;					// オート速度(100:瞬間-0:遅い)
		kag.afterauto   = true;					// 選択後の auto (true:継続, false:停止)
		kag.autoModeWaitVoice = 0;				// オートプレイ更新タイミング (0:ボイス, 2:メッセージ)

		kag.skipStyle = 0;						// 高速スキップ (0:通常, 2:高速＝テキストのみ更新)

		// 隠し設定
		kag.chDefaultFace = global.MessageDefaultFontFace; //"ＭＳ ゴシック";	// フォント
		kag.cancelAutoWhenClick = false;		// クリックでオート停止 (true:有効, false:無効)
		kag.nosewhenskip = true;				// スキップ時の単発SE (true:鳴らさない, false:鳴らす)
	}

	//--------------------------------------------------------------
	if (section("3sound")) {
		// 音の有効, 音量設定
		kag.waveenable       = true; kag.wavevolume       =  50; // 全体音量
		kag.bgmenable        = true; kag.bgmvolume        =  50; // BGM
		kag.seenable         = true; kag.sevolume         =  50; // 効果音
//		kag.hseenable        = true; kag.hsevolume        =  50; // HシーンSE (※hse, hlseオブジェクト効果音)
//		kag.sysseenable      = true; kag.syssevolume      =  50; // システム効果音（専用の設定がある場合のみ／設定がない場合は効果音に連動）
//		kag.bgv2enable       = true; kag.bgv2volume       =  70; // HシーンBGV (hvoice=指定／通常のBGV[bvoice=]の設定がある作品では場合はbgvで指定)
		kag.voiceenable      = true; kag.voicevolume      = 100; // ボイス全体音量
		kag.movieaudioenable = true; kag.movieaudiovolume =  70; // ムービー音量

		// ボイス再生時のBGM音量
		kag.bgmdown          = false;				// 機能有効(true:下げる, false:下げない)
		kag.bgmdownlevel     =  50;					// 下げる割合（0-100%）

		kag.voicecut         = false;				// ボイスをカット
		kag.voicecutpage     = true;				// カットするタイミング（true:ページ消去時にカット, false:名前表示時にカット)
	}

	//--------------------------------------------------------------
	if (section("4voice")) {
		// システムボイス
		with (SystemVoice) {
			.enabled    = true;
			.charmask   = .charmaskdefault; // システムボイスのキャラ初期選択はsysse.iniの sysvodef.defkeys で決定
		}
		// 個別ボイス
		setVoiceAll(true, 100);					// 全キャラボイスON（一括音量100%）

		// 個別設定 (※voiceXの割り当てはファイル先頭付近を参照）
		//chvol("XXX", 100); 

//		chvol("有里栖", 100); 

	}

	//--------------------------------------------------------------
	if (section("5dialog")) {
		// 確認ダイアログの設定の初期化
		ForeachConfirmDialogTags(function (tag, defval) {
			SystemConfig[tag] = defval; // ※初期値は ↑.ConfirmDialogDefaults にて定義
		} incontextof global);
	}

	//--------------------------------------------------------------
	if (section("7mouse")) {
		// ジェスチャの初期値は上部定義 .mouseGestureDefaults を変更のこと
		var bind = scf.mouseGesture;
		/**/bind = scf.mouseGesture = %[] if (!(bind instanceof "Dictionary"));
		(Dictionary.assign incontextof bind)(SC.mouseGestureDefaults);
		try { kag.mouseGesture.enabled = -1; } catch {} // デフォルト無効にする場合は0

		SC.mouseGestureShowHelp = 300; // 表示するまでの時間(ms) 100-3000
		try { kag.mouseGesture.resetHelpTimer(); } catch {} // 即反映
	}

	//--------------------------------------------------------------
	// 初回起動時(savedataがない)のみの初期化処理
	if (isFirst) {
		// DSoundセカンダリバッファを常に再生成
		setDefaultSystemArgument("wsrecreate", "yes");
		@if (kirikiriz) try { WaveSoundBuffer.freeDirectSound(); } catch {} @endif // [XXX] DirectSound作り直し(kzではwsrecreateが反映される）

		// パッドリピート間隔
		setDefaultSystemArgument("padinterval", 70);

		// フレーム上限を設定
		setDefaultSystemArgument("contfreq", 60);

		// VistaではダブルバッファをDirect3Dに(※吉里吉里2のみ)
		setDefaultSystemArgument("dbstyle", "d3d") if (checkWindowsVersion("vista"));
	}
}

