		"消上速"   => %[ "disp" => KAGEnvImage.CLEAR, trans:"trans立ち上がり速" ], // 消去 元立ち上がり
		"消上遅"   => %[ "disp" => KAGEnvImage.CLEAR, trans:"trans立ち上がり遅" ], // 消去 元立ち上がり

		"出上"     => %[ "disp" => KAGEnvImage.SHOW, trans:"transしゃがみ" ], // 表示 元しゃがみ
		"出上速"   => %[ "disp" => KAGEnvImage.SHOW, trans:"transしゃがみ速" ], // 表示 元しゃがみ
		"出上遅"   => %[ "disp" => KAGEnvImage.SHOW, trans:"transしゃがみ遅" ], // 表示 元しゃがみ
		"消下"     => %[ "disp" => KAGEnvImage.CLEAR, trans:"transしゃがみ" ], // 消去 元しゃがみ
		"消下速"   => %[ "disp" => KAGEnvImage.CLEAR, trans:"transしゃがみ速" ], // 消去 元しゃがみ
		"消下遅"   => %[ "disp" => KAGEnvImage.CLEAR, trans:"transしゃがみ遅" ], // 消去 元しゃがみ

