		"左４"   => %[ "xpos" => int -700 ],
		"左３#"  => %[ "xpos" => int -600 ],
		"左３"   => %[ "xpos" => int -500 ],
		"左２#"  => %[ "xpos" => int -425 ],
		"左２"   => %[ "xpos" => int -350 ],
		"左１#"  => %[ "xpos" => int -275 ],
		"左１"   => %[ "xpos" => int -200 ],
		"中"     => %[ "xpos" => int 0    ],
		"右１"   => %[ "xpos" => int  200 ],
		"右１#"  => %[ "xpos" => int  275 ],
		"右２"   => %[ "xpos" => int  350 ],
		"右２#"  => %[ "xpos" => int  425 ],
		"右３"   => %[ "xpos" => int  500 ],
		"右３#"  => %[ "xpos" => int  600 ],
		"右４"   => %[ "xpos" => int  700 ],
		"右４#"  => %[ "xpos" => int  800 ],

		// yposは直で個別に指定する場合が多いようです
		//"縦デフォルト" => %[ "ypos" => int    0 ],
		//"縦しゃがみ"   => %[ "ypos" => int   50 ],
