	// 指定したオブジェクトに対して storage= コマンドとして処理されます
	// 該当オブジェクトが無い場合は自動生成されます
	// 名前は正規表現指定可能です
	// ------------------------------------------------------------------
	"filenameList" => [
		%[
			"name", /^bgm\d+/,
			"object", "bgm",
		],
		%[
			"name", /^se.+/,
			"object", "se",
		],
		%[
			"name", /^ev.+/,
			"object", "ev",
		],
		%[
			"name", /^bg[0-9]/,
			"object", "stage",
		],
	],

