(function(pxw, pxh=pxw) {
	// 状態記憶
	var face = this.face;
	var ha = this.holdAlpha;

	if (pxw <= 0) pwx = 1;
	if (pxh <= 0) pwh = 1;

	// 作業レイヤ
	var lay = new global.Layer(window, this);
	try {
		// ⇒addAlpha⇒Alpha に変換してα=0の部分を完全に黒にする
