/**
 * 泡エフェクト

[simpleanim script=sanim_bubble_up color=色 count={個数範囲} time={時間範囲} delay={遅延範囲} x={範囲}, opacity={濃度範囲} size={大きさ範囲} ]

  範囲は"a:b"として記述（a～bの間でランダム） / ":"がない場合は固定値
 */
function (elm, entry, error, manager) {
	var lay = kag.temporaryLayer;
	var bubble = function (lay, size, app) {
		with (lay) {
			.setImageSize(size, size);
			.setSizeToImageSize();
			.fillRect(0,0, size, size, 0);
			(Layer.drawEllipse incontextof lay)(app, 0,0, size, size);
		}
	};
	if (typeof global.GdiPlus == "undefined") {
		try {
			Plugins.link("layerExDraw.dll");
		} catch (e) {
			error("プラグインを読み込めません:layerExDraw.dll");
			return;
		}
	}
	var range = function (str) {
		var div = ((string)str).split(":");
		if (div.count <= 1) return +str;
		var a = +div[0], b = +div[1];
		return Math.round(defaultRandomGenerator.random() * (b - a) + a);
	};
	with (elm) {
		var cnt = range(.count);
		if (!cnt) return error("個数指定がありません");

		var app = new GdiPlus.Appearance();
		app.addBrush(+elm.color, 0, 0);

		var bx= kag.scWidth/2;
		for (var i = 0; i < cnt; i++) {
			var size = range(.size);
			bubble(lay, size, app);
			var from = kag.scHeight + size, to = -size;
			var act = %[ image:lay, time:range(.time), delay:range(.delay) ];

			act.y = [ from, to, /*time*/void, .accel ];
			act.x = bx+range(.x);
			act.opacity = .opacity !== void ? range(.opacity) : 255;
			act.cx = (.shakespeed === void ? 0.5 :
					  %[ from:0.5, speed:range(.shakespeed), band:range(.shakeband)/100,
					 calc:function (act,from,to,time,now) {
						 return from + Math.sin(act.speed * now/1000 / Math.PI) * act.band;
					 } ]);
			entry(act);
		}

		invalidate app;
	}
	
}

