/**
 * 多数アイテム移動

[simpleanim script=sanim_multimove_lr file={画像} dir={方向1/-1}|1 count={個数範囲} time={時間範囲} delay={遅延範囲} y={範囲}, opacity={濃度範囲} zoom={大きさ範囲} rotate={回転範囲} rotspeed={回転速度範囲} ]

  範囲は"a:b"として記述（a～bの間でランダム） / ":"がない場合は固定値
 */
function (elm, entry, error, manager) {
	var file = getExistImageName(elm.file);
	if (file != "") {
		var lay = kag.temporaryLayer;
		try {
			lay.loadImages(file);
			lay.setSizeToImageSize();
		} catch (e) {
			var err = e ? ": "+e.message : void;
			error("画像がロードできません:"+file+err);
			return;
		}
		var range = function (str) {
			var div = ((string)str).split(":");
			if (div.count <= 1) return +str;
			var a = +div[0], b = +div[1];
			return Math.round(defaultRandomGenerator.random() * (b - a) + a);
		};
		var dw = lay.width*Math.sqrt(2)/2;
		with (elm) {
			var cnt = range(.count);
			if (!cnt) return error("個数指定がありません");
			var from = -dw, to = kag.scWidth+dw;
			var by = kag.scHeight/2;
			if (.dir < 0) from <-> to;
			for (var i = 0; i < cnt; i++) {
				var act = %[ image:lay, time:range(.time), delay:range(.delay) ];
				act.x = [ from, to, /*time*/void, .accel ];
				act.y = by+range(.y);
				act.zoom = range(.zoom) if (.zoom != "");
				act.opacity = [ .opacity !== void ? range(.opacity) : 255, 0, /*time*/, -1 ];
				if (.rotate !== void) {
					var rot = range(.rotate);
					act.rotate = (.rotspeed === void ? rot :
								  %[ from:rot, speed:range(.rotspeed), calc:function (act,from,to,time,now) {
									  return from + act.speed * now/1000 / Math.PI;
								  } ]);
				}
				entry(act);
			}
		}
	} else {
		error("画像指定が無いかファイルが見つかりません:"+elm.file);
	}
}

