scenario/simpleanim/sprite_sakura_act.tj.source:
function (elm, dummy, log, reg) {
	var calc_vib = function (reg, tag, xy) {
		var prms = reg.getParams(tag, xy+"vib");
		if(!prms || !prms.count) return;
		var ofs = reg.rand();
		var band= reg.makeRandomRange(prms);
		if(!band) return;
		var spd = reg.makeRandomRange([+prms[2], +prms[3]]);
		spd = 1/(spd ? spd : 1000); // [XXX]

		var pi2 = Math.PI*2;
		return [ ofs*pi2, spd*pi2, band ];
	};
	var tag = elm.tag;

	// ゆれ
	var cxvib = calc_vib(reg, tag, "x");
	var cyvib = calc_vib(reg, tag, "y");
	if (cxvib || cyvib) {
		var pend = function (per, tick) { return Math.sin(this[0] + this[1]*tick) * this[2] + 0.5; };
		//dm("vib", "\n"+getPrint(cxvib), "\n"+getPrint(cyvib));
		elm.cx = pend incontextof cxvib if cxvib;
		elm.cy = pend incontextof cyvib if cyvib;
	}

	// 移動
	var theta = reg.getRange(tag, "polar", 90, 0, true);
	var speed = reg.getRange(tag, "polar", 10, 2, true);
	if (speed > 0) with (Math) {
		var v  = speed/1000; 
		var t  = theta * .PI*2 / 360;
		elm.vx = .cos(t) * v;
		elm.vy = .sin(t) * v;
		//dm("move", theta, speed, elm.vx, elm.vy);
	}

};

