		//dm("vib", "\n"+getPrint(cxvib), "\n"+getPrint(cyvib));
		elm.cx = pend incontextof cxvib if cxvib;
		elm.cy = pend incontextof cyvib if cyvib;
	}

	// 移動
	var theta = reg.getRange(tag, "polar", 90, 0, true);
	var speed = reg.getRange(tag, "polar", 10, 2, true);
	if (speed > 0) with (Math) {
		var v  = speed/1000; 
		var t  = theta * .PI*2 / 360;
		elm.vx = .cos(t) * v;
		elm.vy = .sin(t) * v;
		//dm("move", theta, speed, elm.vx, elm.vy);
	}

};

